scwin.vScrenID = "ULDSTF41313.xml";
scwin.pJobTitl = js_jobtitl;
scwin.vACPT_NO = ""; //선택한 건의 접수번호
scwin.vISU_CD = ""; //선택한 건의 종목코드
scwin.vISU_KOR_ABBRV = ""; //선택한 건의 종목약명

scwin.fn_GetPar, scwin.fn_SetPar;
