/********************************************** 
 * 함수명   : fn_ExcelDown()
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown = function() {
    if (dts_List.getTotalRow() > 0) {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_01);
        $c.data.downloadGridViewExcel(grd_List, "ETN LP보유량 마감", "", "3");
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};



//ETN 종목 대상 확인
scwin.fn_checkEtnList = function(dtsObj, procJob) {
    //상장원부 상장대상 조회
    dts_Etn.DataID = "/etn/EtnCodeAct.do?method=searchEtnCode&GUBUN=3&ISUR_CD=";
    dts_Etn.reset();
    if (dtsObj.getTotalRow() == dts_Etn.getTotalRow()) {
        for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
            IsuCd = dtsObj.getCellData(i, "ISU_CD");
            bChecked = false;
            for (var j = 1; j <= dts_Etn.getTotalRow(); j++) {
                if (IsuCd == dts_Etn.getCellData(j, "ISU_CD")) {
                    bChecked = true;
                    break;
                }
            }
            if (bChecked == false) {
                return IsuCd + " " + dtsObj.getCellData(i, "ISU_KOR_ABBRV") + "종목은 ETN상장원부 상장된 종목 아닙니다.";
            }
        }
    } else {
        var errMsg = "";
        errMsg = "LP보유량 마감종목 대상(" + dtsObj.getTotalRow() + ")이 전체 마감대상(" + dts_Etn.getTotalRow() + ") 종목수와 다릅니다.\n";
        if ($c.stf.getObjectValue(cmb_ISUR_CD) != '') {
            errMsg = errMsg + "\n검색조건 '발행회사명'을 '전체'로 하여 " + procJob + " 버튼을 선택하시길 바랍니다.";
        }
        return errMsg;
    }
    return "";
};


//목록 중 추출실패건 유무 확인 
scwin.fn_selectExtractError = function(dtsObj) {
    for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
        var acptNo = dtsObj.getCellData(i, "ACPT_NO");
        var offQty = dtsObj.getCellData(i, "OFFHR_DISCLS_INCDEC_QTY");
        if ("" != acptNo && "0" == offQty) {
            //공시는 제출됬으나 추출값이 없는 케이스
            return dtsObj.getCellData(i, "ISU_KOR_ABBRV");
        }
    }
    return "";
};


//목록 중 상장수량보다 합계수량이 큰 경우 담당자 확인이 불가능하도록 한다.
scwin.fn_selectQtyError = function(dtsObj) {
    for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
        var isuQty = dtsObj.getCellData(i, "ETN_ISU_QTY");
        var totalQty = dtsObj.getCellData(i, "TOTAL_QTY");
        if (parseInt(isuQty) < parseInt(totalQty)) {
            //상장수량보다 합계수량이 큰 경우
            //alert(parseInt(isuQty) + "," + parseInt(totalQty));
            return dtsObj.getCellData(i, "ISU_KOR_ABBRV");
        }
    }
    return "";
};


//시장정보 및 시장감시 데이터 확인 
scwin.fn_isFinalDataReady = function(dtsObj) {
    for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
        var mktQty = dtsObj.getCellData(i, "REGULSS_MKT_HD_QTY");
        var bidQty = dtsObj.getCellData(i, "TDD_BID_QTY");
        var askQty = dtsObj.getCellData(i, "TDD_ASK_QTY");
        if (-1 == mktQty || -1 == bidQty || -1 == askQty) {
            //시정, 시감 데이터가 하나라도 없는 경우
            return false;
        }
    }
    return true;
};
scwin.fn_selectCloseError = function() {
    var url = "/listingCommon.do?SCREN_ID=ULDSTF41313.gfm&SCREN_PROCES_TP_CD=01&method=listGeneralForDynamicName" + "&outputMessageId=CODE_M_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.etnlphdmgt.verifyClose";
    dts_closeStatus.DataID = encodeURI(url);
    dts_closeStatus.reset();
    if (dts_closeStatus.getTotalRow() > 0) {
        if (dts_closeStatus.getCellData(1, 'CD_ID') == '15' && dts_closeStatus.getCellData(1, 'VALUE') == 'Y') {
            return "N";
        } else if (dts_closeStatus.getCellData(1, 'CD_ID') == '15' && dts_closeStatus.getCellData(1, 'VALUE') == 'N') {
            $c.win.alert("ETN 법인제출 마감이 되지 않아 마감처리 불가능합니다.");
            return "Y";
        } else {
            $c.win.alert("ETN 법인제출 마감확인이 되지 않습니다.\n시스템 관리자에게 문의 하시기 바랍니다.");
            return "Y";
        }
    } else {
        $c.win.alert("ETN 법인제출 마감확인이 되지 않습니다.\n시스템 관리자에게 문의 하시기 바랍니다.");
        return "Y";
    }
};


//담당자 확인 버튼 클릭시
scwin.fn_revw = function() {
    procJob = "담당자 확인";
    var errMsg = scwin.fn_checkEtnList(dts_List, procJob); // by lds323
    if ('' != errMsg) {
        $c.win.alert(errMsg);
        return false;
    }
    var wrongIsuCd = scwin.fn_selectExtractError(dts_List);
    var wrongQtyCd = scwin.fn_selectQtyError(dts_List);
    var wrongClose = scwin.fn_selectCloseError();

    //alert(wrongIsuCd);
    if ("Y" == wrongClose) {
        return false;
    } else if ('' != wrongIsuCd) {
        $c.win.alert("마감 대상종목 중 정규시장 외 취득/처분 보고 추출실패건이 포함되어 있습니다. \n정규시장외 공시증감수량내역을 확인하세요. \n 해당종목 : " + wrongIsuCd);
        return false;
    } else if ('' != wrongQtyCd) {
        $c.win.alert("마감 대상종목 중 상장수량보다 합계수량이 큰 건이 포함되어 있습니다. 합계수량을 확인하세요. \n 해당종목 : " + wrongQtyCd);
        return false;
    } else {
        var res = window.confirm(procJob + " 마감처리 하시겠습니까?");
        if (res) {
            scwin.fn_trs_revw();
        }
    }
};




// 팀장승인 버튼 클릭시
scwin.fn_aprv = function() {
    procJob = "팀장승인";
    if ($c.stf.getObjectValue(txb_CONFRM_DDTM) == "") {
        $c.win.alert("담당자확인 완료 후 승인처리 가능합니다.");
        return false;
    } else {
        var errMsg = scwin.fn_checkEtnList(dts_List, procJob); // by lds323
        if ('' != errMsg) {
            $c.win.alert(errMsg);
            return false;
        }
        var res = window.confirm(procJob + " 마감처리 하시겠습니까?");
        if (res) {
            scwin.fn_trs_aprv();
        }
    }
};




//담당자 확인
scwin.fn_trs_revw = function() {
    //transaction을 위한 세팅
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        dts_List.setCellData(i, "CHECK", "T");
    }
    //alert(dts_Process.CountRow);
    trs_revw.Action = "/etn/EtnLpMgt.do?method=revwFinalSave&CHRG_EMP_NO=" + js_emp_no + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_revw.KeyName = "toinb_dataid4";
    trs_revw.KeyValue = "JSP(I:pInput=dts_List)";
    trs_revw.Post();
};


//팀장승인 
scwin.fn_trs_aprv = function() {
    //transaction을 위한 세팅
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        dts_List.setCellData(i, "CHECK", "T");
    }
    trs_aprv.Action = "/etn/EtnLpMgt.do?method=aprvFinalSave&APPROVR_EMP_NO=" + js_emp_no + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_aprv.KeyName = "toinb_dataid4";
    trs_aprv.KeyValue = "JSP(I:pInput=dts_List)";
    trs_aprv.Post();
};


