//안내문 작성  - 당일 전부보유목록 
scwin.fn_dscl = async function() {
    var vBzProcsNo = "";

    //2010.07.23 업무처리번호 유무 - 정정공시를 위해 
    scwin.fn_getBzProcsNo();
    vBzProcsNo = dts_BzProcsNo.getCellData(1, "BZ_PROCS_NO");
    if (vBzProcsNo == "") vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
    if (vBzProcsNo.length != 14) {
        $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        return;
    }
    if ($c.stf.getObjectValue(cmb_ISUR_CD) != "") {
        $c.win.alert("안내문작성을 위해 발행회사를 전체로 하여 다시 조회합니다");
        $c.stf.setObjectValue(cmb_ISUR_CD, "");
        scwin.fn_list_sync();
    }
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    scwin.fn_GetPar = function(arr, param_dts_List, param_dts_NOW_DD) {
        arr[0] = "68377";
        arr[1] = vBzProcsNo;
        arr[2] = '99999'; //거래소코드
        arr[3] = '1'; //시장구분


        //dts_NOW_DD.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_NOW_DD.insertRow();
        dts_NOW_DD.setCellData(1, "TASK_DD", $c.stf.getObjectValue(edt_ConfirmDate));
        $c.stf.CopyDataSet(dts_List, param_dts_List);
        $c.stf.CopyDataSet(dts_NOW_DD, param_dts_NOW_DD);
        return arr.length;
    };
    scwin.fn_SetPar = function(arr) {

    };
    var wth = 730 + 5;
    var hgt = 785 + 30;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;
};
scwin.fn_getBzProcsNo = function() {
    var url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=CODE_ETN_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.etnlphdmgt.select.bzprocsno" + "&{P}param01=" + $c.stf.getObjectValue(edt_ConfirmDate);
    dts_BzProcsNo.DataID = encodeURI(url);
    dts_BzProcsNo.reset();
};
